import{_ as e,o as l,c as a,a2 as r}from"./chunks/framework.BWuWLRhz.js";const x=JSON.parse('{"title":"设置中心参考","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/index.md","filePath":"zh-CN/user-guide/settings/index.md","lastUpdated":1787982919000}'),n={name:"zh-CN/user-guide/settings/index.md"};function s(d,t,i,o,g,h){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="设置中心参考" tabindex="-1">设置中心参考 <a class="header-anchor" href="#设置中心参考" aria-label="Permalink to &quot;设置中心参考&quot;">​</a></h1><p>Lertaro 提供了极其丰富且细致的个性化配置选项。无论你是想要微调搜索框的像素级尺寸、定制全局热键、调整不同磁盘的索引频率，还是管理第三方插件与工作区，都可以在设置中心中完成。</p><h2 id="_1-窗口特性与即时交互" tabindex="-1">1. 窗口特性与即时交互 <a class="header-anchor" href="#_1-窗口特性与即时交互" aria-label="Permalink to &quot;1. 窗口特性与即时交互&quot;">​</a></h2><ul><li><strong>自适应窗口与全键盘操作</strong>：设置窗口支持自由拖拽边框调整宽高、双击标题栏最大化，并自动记住你调整的尺寸。</li><li><strong>全局设置模糊搜索</strong>：设置窗口标题栏右上角内置了全局设置搜索框。搜索算法采用与主搜索相同的 fzf 模糊匹配与拼音别名引擎。输入关键词即可跨所有分区（包括插件配置与动态动作）检索选项，回车即可瞬间跳转至目标页面并闪烁高亮该控件。</li><li><strong>防溢出标签栏导航</strong>：在包含多层子标签页的分区（如通用、热键、索引等）中，当标签文本较长时两端会自动呈现滚动箭头，确保在任何语言环境下标签均能完整查看。</li></ul><h2 id="_2-设置分区总览" tabindex="-1">2. 设置分区总览 <a class="header-anchor" href="#_2-设置分区总览" aria-label="Permalink to &quot;2. 设置分区总览&quot;">​</a></h2><p>设置窗口左侧导航栏共包含以下十个核心分区：</p><table tabindex="0"><thead><tr><th style="text-align:left;">分区模块</th><th style="text-align:left;">核心管理内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="./service-status.html">运行状态</a></strong></td><td style="text-align:left;">后台 Windows 服务的运行状态、健康度监控，以及 Service / App / Hook 三大进程的实时日志查看器。</td></tr><tr><td style="text-align:left;"><strong><a href="./index-drives.html">索引管理</a></strong></td><td style="text-align:left;">本地磁盘（NTFS / ReFS / FAT32）、网络共享驱动器（SMB / NAS）、WSL 子系统发行版、自定义文件夹及三类排除规则。</td></tr><tr><td style="text-align:left;"><strong><a href="./general.html">通用设置</a></strong></td><td style="text-align:left;">开机自启、硬件加速、IPC 兼容服务、搜索框像素级尺寸布局、主窗口表格列排序与预览窗口参数。</td></tr><tr><td style="text-align:left;"><strong><a href="./hotkeys-page.html">热键绑定</a></strong></td><td style="text-align:left;">全局呼出快捷键、功能热键、插件专属动作快捷键，以及前台进程黑名单与全屏放行规则。</td></tr><tr><td style="text-align:left;"><strong><a href="./plugins.html">插件管理</a></strong></td><td style="text-align:left;">已安装插件列表、各组件独立开关、插件表单配置面板，以及 Flow Launcher 社区插件生态管理。</td></tr><tr><td style="text-align:left;"><strong><a href="./localsend.html">LocalSend 传输</a></strong></td><td style="text-align:left;">兼容 LocalSend 官方客户端的局域网无线传输协议配置（设备名称、端口、PIN 码与自动保存）。</td></tr><tr><td style="text-align:left;"><strong><a href="./favorites.html">收藏夹</a></strong></td><td style="text-align:left;">常用文件夹、文件与网址的星标别名收藏，支持拖拽排序与拼音检索。</td></tr><tr><td style="text-align:left;"><strong><a href="./history.html">历史记录</a></strong></td><td style="text-align:left;">搜索结果命中历史与输入关键词历史的管理、智能召回及清理。</td></tr><tr><td style="text-align:left;"><strong><a href="./quick-launch.html">快速启动</a></strong></td><td style="text-align:left;">管理手动快速启动项目，并选择哪些动态数据源显示在快速搜索窗口的空白状态下。</td></tr><tr><td style="text-align:left;"><strong><a href="./quick-panel.html">快速面板</a></strong></td><td style="text-align:left;">停靠在活动窗口旁的浮动工作区、多来源文件夹聚合、文件拖入接收与插件动态标签页。</td></tr><tr><td style="text-align:left;"><strong><a href="./appearance.html">外观与主题</a></strong></td><td style="text-align:left;">浅色/深色/跟随系统模式切换，以及自带与随包精选主题卡片的实时缩略图预览。</td></tr><tr><td style="text-align:left;"><strong><a href="./about.html">关于与更新</a></strong></td><td style="text-align:left;">各组件版本号、用户与机器数据目录快速直达、数据备份轮转机制与一键静默升级。</td></tr></tbody></table><p>以下各章节将按顺序列出每一个设置分区的详细选项、参数范围与默认行为。</p>',8)])])}const y=e(n,[["render",s]]);export{x as __pageData,y as default};
